import{_ as t,o as a,c as n,ak as o}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy quest curriculum: Web3, blockchain and AI learning journey","description":"Historical snapshot taken before v2 adoption on October 23, 2026. Not active requirements or current progress. See the adoption archive.","frontmatter":{"title":"Chainy quest curriculum: Web3, blockchain and AI learning journey","description":"Historical snapshot taken before v2 adoption on October 23, 2026. Not active requirements or current progress. See the adoption archive.","source":"docs/archive/pre-v2-adoption-2026-10-23/docs/planning/quest-curriculum.md","category":"Archive","sourceUpdated":"2026-10-23T16:51:22+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/archive/pre-v2-adoption-2026-10-23/docs/planning/quest-curriculum.md","filePath":"content/docs/archive/pre-v2-adoption-2026-10-23/docs/planning/quest-curriculum.md"}'),i={name:"content/docs/archive/pre-v2-adoption-2026-10-23/docs/planning/quest-curriculum.md"};function r(s,e,d,c,l,p){return a(),n("div",null,[...e[0]||(e[0]=[o('<div><h1 id="chainy-quest-curriculum-web3-blockchain-and-ai-learning-journey">Chainy quest curriculum: Web3, blockchain and AI learning journey<a class="header-anchor" href="#chainy-quest-curriculum-web3-blockchain-and-ai-learning-journey" aria-label="Link to this section">​</a></h1><blockquote><p>Historical snapshot taken before v2 adoption on October 23, 2026. Not active requirements or current progress. See the <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/readme.html">adoption archive</a>.</p></blockquote><p><strong>Status:</strong> Draft for Sherwin&#39;s learning-design decisions; not school-approved curriculum. <strong>Audience:</strong> Learners aged 12–17; offline-first Android game. <strong>Source:</strong> <em>Web3 Young Learners Encyclopedia</em>, Cryptita Plays / Bitget, provided PDF, A–Z entries A/01–Z/26 (PDF pages 8–33), with safety and glossary supplements (PDF pages 35–38). The book says it is for understanding, not trading or investing (PDF page 38).</p><h2 id="design-boundaries">Design boundaries<a class="header-anchor" href="#design-boundaries" aria-label="Link to this section">​</a></h2><ul><li>Sequence concepts from familiar digital life and safe participation toward how records and applications work, then synthesis. The encyclopedia is alphabetical; this quest order is a proposed teaching sequence, not the book&#39;s order.</li><li>Keep the adopted experience: compact explorable level, dialogue/learning interactions, and the existing Quiz, Wordle and BlockMatch modes. A quest is a short learning stop in that journey, not a new game mode or a promise of one new level per topic.</li><li>Sherwin decides the learner journey and approves which concepts go where. Sean authors final project documents, learner-facing dialogue and questions from Sherwin&#39;s decisions. Christian implements mechanics, game logic, content/data interfaces and saves. Miguel implements UI. Luis provides visuals.</li><li>Use synthetic examples, fictional tokens and offline scenarios. No wallet connection, QR scanning, exchange use, real crypto, trading advice, participant information or network service is needed.</li><li>The provided encyclopedia covers Web3/blockchain/crypto but has no AI curriculum. Do not present its content as an AI source. Sherwin&#39;s separate AI scope card must identify suitable approved learning references and hand the selected outcomes to Sean for authored materials.</li></ul><h2 id="proposed-quest-log-sequence">Proposed quest log sequence<a class="header-anchor" href="#proposed-quest-log-sequence" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Order</th><th>Quest</th><th>Learning outcome</th><th>Encyclopedia anchors</th><th>Existing mechanic fit</th></tr></thead><tbody><tr><td>0</td><td>Explorer&#39;s safety briefing</td><td>Identify personal/private information, recognize pressure and suspicious links, and choose a safe next step. Establish “learn, question, ask a trusted adult”; no real-world transaction.</td><td>I Identity and Online Safety (p.16); Q QR Codes (p.24); R Risks, Red Flags &amp; Scam-Safe (p.25); U Web3 Safety (p.28); Y Data and Privacy (p.32); supplements pp.36–38</td><td>Intro dialogue and small scenario choice; short baseline questions only if the approved evaluation protocol calls for them.</td></tr><tr><td>1</td><td>Digital value and tokens</td><td>Distinguish government-issued fiat from cryptocurrency; explain that a token/altcoin is a kind of digital asset and does not automatically have stable or real-world value.</td><td>F Fiat (p.13); C Cryptocurrency (p.10); A Altcoins (p.8); T Tokens (p.27); V Volatility (p.29)</td><td>Dialogue/example sort followed by Quiz; no market-price guessing or investment prompt.</td></tr><tr><td>2</td><td>The shared record book</td><td>Describe a ledger and how transactions are grouped into blocks on a blockchain; explain that recorded history is designed to be difficult to alter, not magically immune to every risk.</td><td>L Ledger (p.19); B Blockchain (p.9); glossary: Block, Immutable, Blockchain Explorer (p.35)</td><td>Explore a visual block/ledger exhibit; BlockMatch may pair terms with roles after Sherwin approves the board/rules.</td></tr><tr><td>3</td><td>How a network agrees</td><td>Explain decentralization as shared control, and compare at a high level how proof-of-work miners and proof-of-stake validators participate in network agreement. Note that networks differ.</td><td>D Decentralization (p.11); M Mining &amp; Validators (p.20); P Proof Systems (p.23); glossary: Consensus and Node (p.35)</td><td>Dialogue and a bounded matching/comparison activity using the existing BlockMatch; do not build a mining simulation.</td></tr><tr><td>4</td><td>Wallets, keys and privacy</td><td>Tell a public receiving address from a private key/seed phrase; explain a wallet&#39;s role and choose actions that protect privacy and secrets.</td><td>K Keys (p.18); W Wallets (p.30); I Identity and Online Safety (p.16); Y Data and Privacy (p.32); Z Zero-Knowledge Proofs (p.33)</td><td>Safe/unsafe scenario and word clues; private secrets are never entered into the app. Introduce zero-knowledge only with an age-appropriate “prove without revealing” analogy.</td></tr><tr><td>5</td><td>What happens in an app</td><td>Distinguish on-chain from off-chain activity; describe gas as a network-use fee; explain a smart contract as code that follows specified conditions and a dApp as an application using blockchain.</td><td>O On-chain vs Off-chain (p.22); G Gas Fees (p.14); S Smart Contracts (p.26); glossary: dApp, Testnet (p.35)</td><td>Follow a fictional action through dialogue/diagram and Quiz; no real transaction, testnet, exchange or code execution.</td></tr><tr><td>6</td><td>Digital items and trade-offs</td><td>Explain that NFTs are distinct tokens and tokenized ownership does not guarantee value or other rights; identify volatility and exchange scams as reasons to pause and verify.</td><td>N NFTs (p.21); T Tokens (p.27); E Exchanges, know what not how (p.12); V Volatility (p.29); R Risks (p.25)</td><td>Analyze a fictional collectible/reward example and label known/unknown claims. Never imply purchase, profit or guaranteed ownership rights.</td></tr><tr><td>7</td><td>Chainy concept trail</td><td>Reconstruct the beginner journey: digital value → ledger/blockchain → network agreement → wallet/privacy → app/transaction → digital items and risks. Explain one choice and one safety rule in the learner&#39;s own words.</td><td>Review of the selected A–Z anchors above; glossary and safety supplements</td><td>Existing Quiz for retrieval, Wordle for approved vocabulary, BlockMatch for concept/role matching. Completion is game progress only, not evidence of validated learning gains.</td></tr><tr><td>Separate strand</td><td>AI: scope before content</td><td>Sherwin identifies a small, age-appropriate set of AI fundamentals relevant to the project mission and supplies vetted references and learner outcomes. Keep AI&#39;s relationship to Web3 clear; it is a separate strand.</td><td><strong>No AI entry in the provided encyclopedia&#39;s A–Z or bonus glossary.</strong></td><td>After approved outcomes and references, Sean authors content; Christian checks feasibility/accuracy and implements only approved interactions. No AI model or online AI service is implied.</td></tr></tbody></table><h2 id="mechanics-and-assessment-handoff">Mechanics and assessment handoff<a class="header-anchor" href="#mechanics-and-assessment-handoff" aria-label="Link to this section">​</a></h2><p>For each selected concept, Sherwin&#39;s design decision should specify the learning goal, prerequisite concept, player action, evidence of reasoning, immediate feedback, and the approved location/mechanic. Use Quiz for a small number of concept-aligned checks, Wordle only for key vocabulary, and BlockMatch only where matching relationships is the intended reasoning. Dialogue/exploration provides context. No mechanic should reward speed or guessing in a way that substitutes for explaining the concept.</p><p>The encyclopedia supplies topic explanations and examples, not a formally validated curriculum, local school alignment, or approval to evaluate learners. Sean should adapt and review terminology, examples and assessment items before learner use. Any research/evaluation instrument or learner data collection remains subject to the separately approved school protocol. Keep internal development checks synthetic.</p><h2 id="open-decisions">Open decisions<a class="header-anchor" href="#open-decisions" aria-label="Link to this section">​</a></h2><ol><li>Sherwin chooses the final subset and confirms the order, age-appropriate depth and intended learning outcome for each stop.</li><li>Christian confirms how many quest stops the compact level can support without displacing the current integration and QA window.</li><li>Sherwin identifies approved AI references and defines the separate AI learning outcomes; the provided PDF cannot supply them.</li><li>Sean authors final player-facing text after those decisions. Miguel and Christian receive explicit screen and logic handoffs.</li></ol></div>',1)])])}const g=t(i,[["render",r]]);export{u as __pageData,g as default};
